from pathlib import Path
import datetime,json,runpy
OWN=Path(__file__).parent
def write(n,x):
    p=OWN/n;assert not p.exists(),p;p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
ids=json.loads((OWN/'selected-eighteen-current-goal-ids.author.json').read_text())
goals=json.loads((OWN/'current-eighteen-whole-DEEN-goals.actual.json').read_text())['wholeGoals']
cases=sum([runpy.run_path(str(OWN/f'author-case-library.part{i}.actual.py'))['CASES'] for i in [1,2,3]],[])
assert len(cases)==36 and len({c['id'] for c in cases})==36
for c in cases:
    c['goalId']=ids[c['ordinal']-1]
    for field in ['material','task','modelAnswer']:
        assert all(c[field][lang].strip() for lang in ['de','en'])
ESS=[
('Fossilien, Homologien und Endosymbiontentheorie liefern verschiedenartige, begründet miteinander verknüpfbare Evolutionsbelege.','Fossils, homologies, and endosymbiotic theory provide different kinds of evolutionary evidence that can be related through reasoned interpretation.','Gemeinsame Funktion wird von Homologie, Fossilfolge von sicherer direkter Abstammung und Organell-Einzelbefund von einer umfassenden Herkunftshypothese unterschieden.','Shared function is distinguished from homology, fossil succession from certain direct ancestry, and a single organelle observation from a comprehensive origin hypothesis.'),
('Allopatrische und sympatrische Prozesse unterscheiden sich in geografischer Ausgangstrennung, Genfluss und Entwicklung reproduktiver Barrieren.','Allopatric and sympatric processes differ in initial geographical separation, gene flow, and development of reproductive barriers.','Wirte, Orte und Chromosomenzahlen werden als begründete Mechanismen eingeordnet, ohne eine einzelne Trennung automatisch als dauerhaft etablierte Art zu zählen.','Hosts, locations, and chromosome counts are interpreted as reasoned mechanisms without automatically counting one separation as a permanently established species.'),
('Menschenentwicklung wird über Fossilgeschichte, hypothetische verzweigte Stammbäume und Ausbreitungsbefunde beschrieben.','Human evolution is described through the fossil record, hypothetical branching phylogenetic trees, and dispersal evidence.','Fundlücken, zeitliche Überlappung und Genfluss werden berücksichtigt; es entsteht keine Rangfolge heutiger Menschen oder direkte Abstammung von heute lebenden Menschenaffen.','Gaps, temporal overlap, and gene flow are considered without ranking present-day humans or claiming direct descent from present-day apes.'),
('Werkzeuggebrauch und Sprachentwicklung können kulturelle Weitergabe, Kooperation und kumulative Veränderungen ermöglichen.','Tool use and language development can support cultural transmission, cooperation, and cumulative change.','Kulturelles Lernen wird von genetischer Vererbung und archäologischer Beleg von unbelegten Aussagen über den genauen Sprachbeginn getrennt.','Cultural learning is distinguished from genetic inheritance, and archaeological evidence from unsupported claims about the exact origin of language.'),
('Soziale Reize und Umwelteinflüsse wirken bei Primaten mit endogenen Zuständen in unmittelbaren Verhaltensursachen zusammen.','Social stimuli and environmental factors interact with endogenous states as proximate causes of primate behavior.','Beobachtungszusammenhänge werden kontrolliert und von Kausalnachweis, evolutivem Nutzen und menschlichen Sollensregeln getrennt.','Observational relationships are checked and distinguished from established causation, evolutionary benefit, and human prescriptions.'),
('Historischer Missbrauch evolutionärer Vorstellungen wird über biologische Fehlbehauptungen, ideologische Wertungen und deren Konsequenzen analysiert.','Historical misuse of evolutionary ideas is analyzed through biological errors, ideological judgments, and their consequences.','Biologische Fitness begründet keinen Menschenwert; aus biologischen Beschreibungen folgen keine moralischen Erlaubnisse zu Zwang oder Entrechtung.','Biological fitness does not establish human worth; biological descriptions do not entail moral permission for coercion or denial of rights.'),
('Allopatrische, sympatrische und hybridisierungsbezogene Wege werden nach Ausgangssituation, Genfluss und reproduktiver Isolation verglichen.','Allopatric, sympatric, and hybridization-related routes are compared by initial conditions, gene flow, and reproductive isolation.','Hybriden, Introgression, Polyploidisierung und eine sich selbst erhaltende neue Linie werden begründet unterschieden.','Hybrids, introgression, polyploidization, and a self-sustaining new lineage are distinguished through evidence.'),
('Molekulare Distanz, kalibrierte Substitutionsrate und die Definition als Einzelast- oder Paar-Rate bestimmen eine bedingte Zeitschätzung.','Molecular distance, calibrated substitution rate, and its definition as a single-branch or pairwise rate determine a conditional time estimate.','Rateheterogenität, Kalibrier- und Sequenzunsicherheit begrenzen die Datierung und werden ohne scheinpräzise Mittelwerte eingeordnet.','Rate heterogeneity and calibration/sequence uncertainty limit dating and are assessed without falsely precise averages.'),
('Hypothesen zur Hominidenentwicklung und kulturellen Evolution werden mit getrennten Fossil-, genetischen und Kulturbelegen verglichen.','Hypotheses on hominin development and cultural evolution are compared using distinct fossil, genetic, and cultural evidence.','Merkmalsmosaike und Lernweitergabe begründen vorläufige Verzweigungshypothesen ohne zwangsläufige Fortschrittsreihe oder Gleichsetzung von Kultur und Genetik.','Trait mosaics and learned transmission support tentative branching hypotheses without an inevitable ladder of progress or equating culture with genetics.'),
('Stabilisierende, gerichtete und disruptive Selektion werden durch vererbbare Variation und systematische Unterschiede des Fortpflanzungsbeitrags erklärt.','Stabilizing, directional, and disruptive selection are explained through heritable variation and systematic differences in reproductive contribution.','Überleben wird in den Gesamtbeitrag eingeordnet; zufällige Verteilungsänderung und begünstigte Extreme beweisen weder gerichtete Selektion noch abgeschlossene Artbildung.','Survival is related to total contribution; random distributional change and favored extremes establish neither directional selection nor completed speciation.'),
('Fitnesslandschaften beschreiben genotyp- und umweltabhängige Fortpflanzungsbeiträge und erlaubte Änderungen zwischen expliziten Nachbarn.','Fitness landscapes represent genotype- and environment-dependent reproductive contributions and permitted changes between explicit neighbors.','Lokale und globale Maxima werden unterschieden; Kontextwechsel und ausgelassene Prozesse begrenzen die strikte adaptive Pfadregel.','Local and global maxima are distinguished; contextual changes and omitted processes limit a strict adaptive-path rule.'),
('Koevolution erfordert wechselseitige Selektionswirkungen und evolutionäre Antworten, nicht nur ähnliche Formen oder räumliches Zusammenleben.','Coevolution requires reciprocal selection and evolutionary responses rather than similar shapes or spatial coexistence alone.','Partnerwechsel, Zeitvergleich und Kontrollen werden als Evidenz eingeordnet, ohne Kooperation, Kausalgeschichte oder einen perfekten Endzustand vorauszusetzen.','Partner differences, temporal comparisons, and controls are interpreted without presupposing cooperation, complete causal history, or a perfect endpoint.'),
('Diploide Genotypzählung bestimmt den Genpool mit zwei Allelkopien je Individuum; Heterozygote tragen zu beiden Allelfrequenzen bei.','Diploid genotype counts determine a gene pool with two allele copies per individual; heterozygotes contribute to both allele frequencies.','Genfluss und sichtbare Phänotypen werden von Allelfrequenz und nicht vorausgesetztem genetischem Gleichgewicht unterschieden.','Gene flow and visible phenotypes are distinguished from allele frequencies and an unassumed genetic equilibrium.'),
('Hardy-Weinberg liefert p²,2pq,q² als Genotyp-Erwartungen unter angegebenen idealisierten Bedingungen.','Hardy-Weinberg supplies p²,2pq,q² as genotype expectations under specified idealized conditions.','Abweichungen und aus Phänotypen abgeleitete Werte werden als bedingte Modellschlüsse geprüft, ohne eine einzelne Ursache oder reales Gleichgewicht zu erfinden.','Deviations and phenotype-derived values are evaluated as conditional model inferences without inventing a unique cause or an actual equilibrium.'),
('Drift verändert Allelfrequenzen zufällig; Flaschenhals und Gründerstichprobe sind unterschiedliche demografische Ausgangspunkte kleiner Genpools.','Drift changes allele frequencies by chance; bottlenecks and founder samples are different demographic starting points for small gene pools.','Allelhäufigkeiten und vorgegebene Stichprobenwahrscheinlichkeiten werden berechnet, ohne Zufall als Fitnessnachweis oder das Fehlen eines Genotyps als Allelverlust zu deuten.','Allele frequencies and specified sampling probabilities are calculated without treating chance as a fitness advantage or genotype absence as allele loss.'),
('Sexuelle Selektion verändert Zugang zur Fortpflanzung über Partnerwahl oder Konkurrenz; Fitness berücksichtigt erfolgreiche Nachkommen und Überlebenskosten.','Sexual selection alters reproductive access through mate choice or competition; fitness includes successful offspring and survival costs.','Umweltabhängige Kosten-Nutzen-Vergleiche werden begründet, ohne auffällige Merkmale als immer vorteilhaft oder menschliche Rollen als biologisch vorgeschrieben zu erklären.','Environment-dependent cost-benefit comparisons are justified without treating conspicuous traits as always advantageous or human roles as biologically prescribed.'),
('Kladistische Rekonstruktion nutzt homologe gemeinsame abgeleitete Merkmale; orthologe Sequenzen ergänzen das Verwandtschaftssignal.','Cladistic reconstruction uses homologous shared derived characters; orthologous sequences supplement relationship evidence.','Außengruppe, Homoplasie und widersprüchliche Daten werden geprüft; der phylogenetische Baum ist keine Rangliste oder individuelle Familiengenealogie.','Outgroups, homoplasy, and conflicting data are checked; a phylogenetic tree is neither a ranking nor an individual family genealogy.'),
('Alignierte orthologe Sequenzen liefern geteilte Änderungen und Distanzen zur Begründung phylogenetischer Hypothesen.','Aligned orthologous sequences supply shared changes and distances for justified phylogenetic hypotheses.','Kurze und widersprüchliche Gen-Signale werden mit Unsicherheit interpretiert; ein Genbaum oder kleine Distanz legt nicht automatisch Artgeschichte oder direkte Abstammung fest.','Short and conflicting gene signals are interpreted with uncertainty; a gene tree or small distance does not automatically determine species history or direct ancestry.')]
VAR=[('Fossil/Knochen/Organell-Mosaik gegenüber Funktionskonvergenz und Chloroplasten.','Fossil/bone/organelle mosaic versus functional convergence and chloroplasts.'),('Geografische Barriere/Wirtswechsel gegenüber Polyploidisierung und kreuzbaren Inselbeständen.','Geographical barrier/host shift versus polyploidization and interfertile island populations.'),('Datierte Fundkarte gegenüber überlappenden Menschenlinien und begrenztem Genfluss.','Dated find map versus coexisting human lineages and limited gene flow.'),('Lernweitergabe mit/ohne Sprache gegenüber gruppenübergreifender Technik und genetischer Vererbung.','Transmission with/without language versus intergroup technology and genetic inheritance.'),('Futter-/Fortpflanzungskontext gegenüber Gruppenwechsel, Stress und unkontrollierter Korrelation.','Food/reproduction context versus group change, stress, and uncontrolled correlation.'),('NS-Eugenik und Fitnessbegriff gegenüber aktuellem politischen Fehlschluss und historischer Quellenkritik.','Nazi eugenics and fitness versus a present-day political fallacy and historical source criticism.'),('Drei Wege einschließlich Polyploidhybride gegenüber Kontaktzonen und unvollständiger Trennung.','Three routes including polyploid hybrids versus contact zones and incomplete separation.'),('Definierte Einzelast-Rate gegenüber Paar-Rate, zwei Sequenzen und Rateverletzung.','Defined single-branch rate versus pairwise rate, two sequences, and violated rate constancy.'),('Merkmalsmosaik/Sprachhypothese gegenüber Ausbreitung, Genfluss und Kulturweitergabe.','Trait mosaic/language hypothesis versus dispersal, gene flow, and cultural transmission.'),('Drei Selektionsmodi nach Nachkommenbeitrag gegenüber Überlebens-/Paarungskomponenten und Zufallssturm.','Three modes by offspring contribution versus survival/mating components and a random storm.'),('Zwei-Positionen-Nachbarschaft gegenüber lokalem Maximum, höherem Fernmaximum und Umweltwechsel.','Two-position neighborhood versus a local maximum, higher distant maximum, and environmental change.'),('Bestäubungswirkung beider Partner gegenüber Wirt-Parasit-Zeitmatrix.','Reciprocal pollination effects versus a temporal host-parasite matrix.'),('Genotypzählung gegenüber Zuwanderung und dominanten Phänotypen.','Genotype census versus immigration and dominant phenotypes.'),('Erwartete Genotypen bei gegebenen Allelfrequenzen gegenüber rezessivem Phänotyp und ungesicherter kleiner Population.','Expected genotypes from given allele frequencies versus a recessive phenotype and uncertain small population.'),('Erfasster Flaschenhals gegenüber Gründerstichprobe und expliziter Binomialwahrscheinlichkeit.','Observed bottleneck versus a founder sample and explicit binomial probability.'),('Partnerwahl-/Überlebenskonflikt gegenüber Konkurrenz und umweltabhängig umgekehrtem Gesamtnutzen.','Mate-choice/survival trade-off versus competition and reversed overall benefits in another environment.'),('Homologe Merkmalsmatrix/Sequenzvergleich gegenüber Funktionskonvergenz und widersprüchlichen Daten.','Homologous character matrix/sequence comparison versus functional convergence and conflicting data.'),('Alignierte Sequenz und zählbare Unterschiede gegenüber widersprüchlichen unabhängigen Genabschnitten.','Aligned sequence and countable differences versus conflicting independent gene segments.')]
profiles=[]
for i,g in enumerate(goals):
    o=i+1;pair=[c for c in cases if c['ordinal']==o];assert len(pair)==2
    cd,ce,ld,le=ESS[i]; core=f'he-evolution18-{o:02d}-core';limit=f'he-evolution18-{o:02d}-transfer'
    profile={'archetype':'data' if o in [8,10,12,13,14,15,16,18] else 'representation' if o in [3,17] else 'modeling' if o in [2,7,11] else 'concept','expectations':[{'id':core,'essentialUnderstandingDe':cd,'essentialUnderstandingEn':ce,'observablePerformanceDe':pair[0]['task']['de'],'observablePerformanceEn':pair[0]['task']['en']},{'id':limit,'essentialUnderstandingDe':ld,'essentialUnderstandingEn':le,'observablePerformanceDe':pair[1]['task']['de'],'observablePerformanceEn':pair[1]['task']['en']}],'coverageExpectations':{'requiredExpectationIds':[core,limit],'alternativeExpectationGroups':[],'minimumIndependentDemonstrations':2,'freshVariationRequired':True,'independentTransferRequired':True},'variationAxes':[{'id':f'he-evolution18-{o:02d}-context-evidence','textDe':VAR[i][0],'textEn':VAR[i][1]}],'applicationCaseBriefs':[{'id':c['id'],'taskDemandDe':c['material']['de']+' '+c['task']['de'],'taskDemandEn':c['material']['en']+' '+c['task']['en'],'expectedPerformanceDe':c['modelAnswer']['de'],'expectedPerformanceEn':c['modelAnswer']['en'],'understandingFocusDe':cd+' '+ld,'understandingFocusEn':ce+' '+le} for c in pair]}
    profiles.append({'goalId':g['id'],'reason':'Own complete bilingual positive-understanding author candidate for this whole current goal. New source/operator/science judgments await two genuine independent reviews; known smallest two-goal wording corrections are separately proposed and not active. Existing unchanged A/M reuse is not approval of new cases.','evidenceLevel':'E1','maximumClaimScope':'G1','dissent':['Author, not independent reviewer; ai_candidate/needs_human_review, no pupil data or performed experiments.','Actual current official whole pages and bounded didactic source elaborations are separated from normalized rows incorrectly labeled verbatim officialCompetency. Whole source/route overclaims remain explicit pending findings.','Two supplied complete cases are meaningful variations, not an extra-task quota after sufficient actual evidence; transfer within a genuine task can suffice.','No inevitable progress ladder, selection teleology, hierarchy among human populations, or political prescription from evolutionary description.','Numeric model assumptions, clocks per-branch/pair rates, HWE conditionality, drift sampling, and genotype/allele distinctions are explicit.','Source/practical competence is not established by synthetic interpretation alone; these goal descriptions request explain/compare/describe/apply rather than performed wet-lab manipulation.'],'profile':profile})
write('eighteen-whole-goals-thirty-six-complete-DEEN-cases.author.json',{'schemaVersion':1,'authorRole':'Own author candidate; no independent approval','wholeGoalBodies':goals,'wholeCases':cases,'counts':{'goals':18,'wholeDEENCases':36},'performedExperiments':0,'learnerEvidence':False,'sourceOriginalBodiesChanged':False})
write('P18.thirty-six-whole-DEEN-cases.author.candidates.json',{'schemaVersion':1,'authoringContract':'positive-understanding-evidence-candidates-v1','reviewId':OWN.name,'reviewedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'reviewer':'codex-evolution18-whole-science-author-not-independent-reviewer','goals':profiles})
snap=json.loads((OWN/'declared-input-snapshots.actual.json').read_text())
write('P18.whole-current-author.config.json',{'$schema':'https://skillpilot.com/schemas/goal-evidence/v2/goal-evidence-review-config.schema.json','schemaVersion':2,'reviewId':OWN.name,'goalFingerprintRuleVersion':'goal-evidence-v1','profileRuleVersion':'positive-understanding-evidence-v2','landscapeId':'08a43a1b-d97e-522c-9dfa-c950a493364e','landscapePath':snap['curricula/DE/Gymnasium/canonical/DE_DEU_S_GYM_CANONICAL_BIOLOGIE.de.json'],'semanticKindLedgerPath':snap['curricula/DE/Gymnasium/quality/goal-book-publication/biologie.semantic-kinds.json'],'reviewCriteriaPath':snap['curricula/DE/Gymnasium/quality/goal-evidence/prompts/biology-positive-understanding-evidence-profile-criteria-v1.md'],'reviewPath':str((OWN/'P18.whole-current-author.review.jsonl').relative_to(Path.cwd())),'reviewRunManifestPaths':[],'reviewedResourceTypes':[],'requireApproved':False,'scope':{'label':'Eighteen unchanged current HE-derived evolution goals: whole-source author models; science/source boundaries and two-goal wording corrections not yet independently reviewed; raster/nativeD/V pending','goalIds':ids}})
